     1→/**
     2→ * Simulation Web Worker
     3→ *
     4→ * Runs simulation engine in a separate thread to avoid blocking the UI.
     5→ * Communicates via message passing for commands and state updates.
     6→ *
     7→ * Architecture:
     8→ * - Imports same engine code as Monte Carlo (zero duplication)
     9→ * - Sends delta updates (not full 1.78MB state)
    10→ * - Supports pause/resume/step controls
    11→ * - Can inject player decisions (Phase 3 future work)
    12→ */
    13→
    14→// Suppress verbose console logging in worker context to prevent memory overflow
    15→// Individual phases call console.log() directly, ignoring logLevel config
    16→// This prevents browser from accumulating hundreds of console messages per second
    17→const originalLog = console.log;
    18→const originalWarn = console.warn;
    19→// TEMPORARILY ENABLED for debugging population issue
    20→// console.log = () => {}; // Suppress simulation logs
    21→// console.warn = () => {}; // Suppress warnings
    22→// Keep console.error for critical issues
    23→self.addEventListener('error', (e) => {
    24→  originalLog('[Worker Error]', e.message, e.filename, e.lineno);
    25→});
    26→
    27→import { SimulationEngine } from '../simulation/engine';
    28→import { createDefaultInitialState } from '../simulation/initialization';
    29→import type { GameState } from '../types/game';
    30→import type { ScenarioMode } from '../types/game';
    31→import type { LandUseSystem } from '../types/planetaryBoundaries';
    32→
