    36→let running = false;
    37→let simulationIntervalId: ReturnType<typeof setInterval> | null = null; // Monthly simulation steps
    38→let dayIntervalId: ReturnType<typeof setInterval> | null = null; // Daily UI updates
    39→let stepInterval = 30000; // 30 seconds = 1 month (each month takes 30 seconds)
    40→
    41→// Calendar tracking
