    43→let startDate: Date | null = null; // Real calendar start date (preserved for reference)
    44→let currentCalendarDate: Date | null = null; // Current calendar date (incremented each day)
    45→let totalSimulationDaysElapsed = 0; // Total simulation days since initialization
